class Solution {
  public long[] countStableSubarrays(int[] nums, int[][] queries) {
    int n = nums.length;
    int[] runId = new int[n];
    int[] runStart = new int[n], runEnd = new int[n];
    int runs = 0;
    for (int i = 0; i < n; ) {
      int j = i;
      while (j + 1 < n && nums[j + 1] >= nums[j]) j++;
      runStart[runs] = i;
      runEnd[runs] = j;
      for (int t = i; t <= j; t++) runId[t] = runs;
      runs++;
      i = j + 1;
    }
    long[] pre = new long[runs + 1];
    for (int r = 0; r < runs; r++) {
      long len = runEnd[r] - runStart[r] + 1;
      pre[r + 1] = pre[r] + len * (len + 1) / 2;
    }
    long[] ans = new long[queries.length];
    for (int i = 0; i < queries.length; i++) {
      int l = queries[i][0], r = queries[i][1];
      int a = runId[l], b = runId[r];
      if (a == b) {
        long len = r - l + 1;
        ans[i] = len * (len + 1) / 2;
      } else {
        long left = runEnd[a] - l + 1, right = r - runStart[b] + 1;
        ans[i] = left * (left + 1) / 2 + right * (right + 1) / 2 + pre[b] - pre[a + 1];
      }
    }
    return ans;
  }
}
